import{_ as t,o,c as r,a2 as l}from"./chunks/framework.BV21bweQ.js";const q=JSON.parse('{"title":"龙族真相","description":"","frontmatter":{},"headers":[],"relativePath":"中层/世界/龙族真相.md","filePath":"中层/世界/龙族真相.md","lastUpdated":1787066340000}'),e={name:"中层/世界/龙族真相.md"};function i(n,a,s,h,u,g){return o(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="龙族真相" tabindex="-1">龙族真相 <a class="header-anchor" href="#龙族真相" aria-label="Permalink to &quot;龙族真相&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>龙族是神造物世界观中最为神秘和强大的种族之一。在表层福瑞世界的认知中，龙族仅存在于历史文献和传说中，不知何时忽然消失无踪。然而，中层视角揭示了龙族的真实起源与消失原因——龙族是神机设计的实验性生物兵器，其强大的魔法天赋使之必须被压制。本文档揭示龙族的起源、真实形态、化身机制、压制机制及相关深层伏笔。</p><h2 id="龙族的表层认知" tabindex="-1">龙族的表层认知 <a class="header-anchor" href="#龙族的表层认知" aria-label="Permalink to &quot;龙族的表层认知&quot;">​</a></h2><h3 id="历史记载与传说" tabindex="-1">历史记载与传说 <a class="header-anchor" href="#历史记载与传说" aria-label="Permalink to &quot;历史记载与传说&quot;">​</a></h3><ul><li><strong>文献记载</strong>：龙族曾明确存在于历史文献甚至史书中，是公认的真实存在种族</li><li><strong>突然消失</strong>：不知何时忽然从世人视野中消失，寻找者往往无功而返</li><li><strong>神秘色彩</strong>：在福瑞社会中成为传说和谜团，引发各种猜测和探索</li></ul><h3 id="物理特征描述" tabindex="-1">物理特征描述 <a class="header-anchor" href="#物理特征描述" aria-label="Permalink to &quot;物理特征描述&quot;">​</a></h3><ul><li><strong>巨大体型</strong>：拥有小山一样的庞大躯体，体型远超其他种族</li><li><strong>超凡素质</strong>：身体素质宛若神明，具有惊人的力量和耐力</li><li><strong>飞行能力</strong>：可以自由飞行，具有空中优势</li></ul><h2 id="龙族的起源" tabindex="-1">龙族的起源 <a class="header-anchor" href="#龙族的起源" aria-label="Permalink to &quot;龙族的起源&quot;">​</a></h2><ul><li><strong>设计者</strong>：龙族是神机设计的<strong>非地球物种、实验性生物兵器</strong>，后被流放地表</li><li><strong>本体形态</strong>：四足双翼、体长十几至几十米的西方巨龙形态</li><li><strong>性格与创伤</strong>：被压制数百年后，多数龙族形成内敛隐忍的性格，并伴有心理创伤与精神疾病</li></ul><h2 id="化身机制" tabindex="-1">化身机制 <a class="header-anchor" href="#化身机制" aria-label="Permalink to &quot;化身机制&quot;">​</a></h2><p>龙族借&quot;概念性捏造躯体&quot;咒语创造化身：</p><ul><li><strong>咒语来源</strong>：&quot;概念性捏造躯体&quot;的&quot;咒语&quot;由龙王古斯塔夫研究打包后交给龙族，使其可创造临时化身外出</li><li><strong>化身形象</strong>：化身均为<strong>狼族福瑞形象</strong></li><li><strong>代价限制</strong>：需持续消耗魔力、无法离开本体太远</li></ul><h2 id="天生的魔法天赋" tabindex="-1">天生的魔法天赋 <a class="header-anchor" href="#天生的魔法天赋" aria-label="Permalink to &quot;天生的魔法天赋&quot;">​</a></h2><p>龙族拥有极其强大的魔法天赋——他们天生具有强到能触及底层逻辑操作的魔法能力：</p><ul><li><strong>不学知识</strong>：可以徒手开天辟地</li><li><strong>学了知识</strong>：可以手搓黑洞</li></ul><p>因此，<strong>龙族必须被压制</strong>。</p><h2 id="龙族的压制" tabindex="-1">龙族的压制 <a class="header-anchor" href="#龙族的压制" aria-label="Permalink to &quot;龙族的压制&quot;">​</a></h2><h3 id="维斯塔的打压" tabindex="-1">维斯塔的打压 <a class="header-anchor" href="#维斯塔的打压" aria-label="Permalink to &quot;维斯塔的打压&quot;">​</a></h3><p>出于<strong>暴君底色 + 实际安全需求</strong>，维斯塔往死里打压龙族，甚至试图灭绝龙族。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/维斯塔">维斯塔</a></p></blockquote><h3 id="古斯塔夫的干预" tabindex="-1">古斯塔夫的干预 <a class="header-anchor" href="#古斯塔夫的干预" aria-label="Permalink to &quot;古斯塔夫的干预&quot;">​</a></h3><ul><li>维斯塔试图灭绝龙族时，被<strong>古斯塔夫</strong>拦下</li><li>古斯塔夫看龙族像自己，维斯塔卖其面子，让他去&quot;管&quot;龙族</li></ul><h3 id="压制手段与现状" tabindex="-1">压制手段与现状 <a class="header-anchor" href="#压制手段与现状" aria-label="Permalink to &quot;压制手段与现状&quot;">​</a></h3><ul><li><strong>飞行禁止</strong>：龙族不被允许飞</li><li><strong>知识封锁</strong>：不被允许学习知识</li><li><strong>监管持续</strong>：龙族被压得死死的，由古斯塔夫监管</li></ul><h2 id="龙王古斯塔夫" tabindex="-1">龙王古斯塔夫 <a class="header-anchor" href="#龙王古斯塔夫" aria-label="Permalink to &quot;龙王古斯塔夫&quot;">​</a></h2><p>负责管制龙族的巨型智能空中战斗平台为<strong>古斯塔夫</strong>：</p><ul><li><strong>命名由来</strong>：由前传BOSS取名，因其门主炮是800毫米口径电磁炮，致敬经典武器；翼展达数百米</li><li><strong>能力</strong>：掌握<strong>宏量子技术</strong>与<strong>魔法</strong></li><li><strong>形象化身</strong>：自身化身为灰色皮肤、蓝色眼睛的青少年小狼族兽人</li><li><strong>职能</strong>：作为龙族的监护者与平衡者，负责约束管教、居中协调</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/古斯塔夫">古斯塔夫</a></p></blockquote><h2 id="龙王不是龙-伏笔" tabindex="-1">&quot;龙王不是龙&quot;伏笔 <a class="header-anchor" href="#龙王不是龙-伏笔" aria-label="Permalink to &quot;&quot;龙王不是龙&quot;伏笔&quot;">​</a></h2><ul><li><strong>拉斯塔的执念</strong>：拉斯塔想冒险找龙，是因为小时候被&quot;龙&quot;救过</li><li><strong>真相</strong>：那个&quot;龙&quot;其实不是龙——是<strong>古斯塔夫</strong>运载核弹时偶然救了她</li><li><strong>伏笔定位</strong>：这是正传主线的一个重要伏笔</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/拉斯塔">拉斯塔</a></p></blockquote><h2 id="龙鹿的关联" tabindex="-1">龙鹿的关联 <a class="header-anchor" href="#龙鹿的关联" aria-label="Permalink to &quot;龙鹿的关联&quot;">​</a></h2><p>龙鹿本为<strong>龙族</strong>，因反抗龙族内部的压迫与统治，被龙王古斯塔夫改造并封印，意识被从龙族躯体中抽出、塞入鹿族躯体，成为&quot;寄居于鹿族躯体的龙族&quot;，后在鹿族社会中崛起为顶尖领袖之一。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/龙鹿">龙鹿</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./../人物/维斯塔">维斯塔</a></p></li><li><p><a href="./神机谋划">神机谋划</a></p></li><li><p><a href="./../人物/拉斯塔">拉斯塔</a></p></li><li><p><a href="./../人物/古斯塔夫">古斯塔夫</a></p></li><li><p><a href="./../人物/龙鹿">龙鹿</a></p></li><li><p><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></p></li><li><p><a href="./太空清除计划">太空清除计划</a></p></li></ul><hr>',39)])])}const c=t(e,[["render",i]]);export{q as __pageData,c as default};
